package com.shipflow.tracking;import com.shipflow.common.exception.GlobalExceptionHandler;import com.shipflow.order.application.ShipmentOrderException;import com.shipflow.security.SecurityConfig;import com.shipflow.tracking.api.*;import com.shipflow.tracking.api.model.*;import com.shipflow.tracking.application.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.*;import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;import org.springframework.boot.test.context.TestConfiguration;import org.springframework.boot.test.mock.mockito.MockBean;import org.springframework.context.annotation.*;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.oauth2.jwt.JwtDecoder;import org.springframework.test.web.servlet.MockMvc;import java.time.*;import java.util.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest(TrackingQueryController.class)@Import({SecurityConfig.class,GlobalExceptionHandler.class,TrackingQueryControllerWebMvcTest.C.class})class TrackingQueryControllerWebMvcTest{@Autowired MockMvc mvc;@MockBean TrackingQueryApplicationService s;@TestConfiguration static class C{@Bean JwtDecoder jwtDecoder(){return x->{throw new org.springframework.security.oauth2.jwt.BadJwtException("x");};}}@Test void listUsesJwtTenant()throws Exception{when(s.list(7L,9L)).thenReturn(List.of());mvc.perform(get("/api/v1/shipment-orders/9/tracking").with(token())).andExpect(status().isOk()).andExpect(jsonPath("$.success").value(true));verify(s).list(7L,9L);}@Test void statusUsesJwtTenant()throws Exception{when(s.status(7L,9L)).thenReturn(new TrackingStatusResponse(9L,"IN_TRANSIT",null));mvc.perform(get("/api/v1/shipment-orders/9/tracking/status").with(token())).andExpect(status().isOk()).andExpect(jsonPath("$.data.currentStatus").value("IN_TRANSIT"));}@Test void unauthenticatedIs401()throws Exception{mvc.perform(get("/api/v1/shipment-orders/9/tracking")).andExpect(status().isUnauthorized());}@Test void mapsTenantSafeNotFound()throws Exception{when(s.list(7L,9L)).thenThrow(new ShipmentOrderException("COMMON-1006",404));mvc.perform(get("/api/v1/shipment-orders/9/tracking").with(token())).andExpect(status().isNotFound()).andExpect(jsonPath("$.error.code").value("COMMON-1006"));}private org.springframework.test.web.servlet.request.RequestPostProcessor token(){return jwt().jwt(j->j.subject("2").claim("tenant_id","7")).authorities(new SimpleGrantedAuthority("scope:TENANT"));}}
